import type * as adapter from "engine-adapter";

export type SameSite = "strict" | "lax" | "none";
export type CookieOptions = {
    maxAge?: number | undefined;
    expires?: Date | undefined;
    path?: string | undefined;
    domain?: string | undefined;
    secure?: boolean | undefined;
    httpOnly?: boolean | undefined;
    sameSite?: SameSite | undefined;
    partitioned?: boolean | undefined;
};
export type Jar = { get: ( name: string ) => string | undefined; set: ( name: string, value: string, options?: CookieOptions ) => void; remove: ( name: string, options?: CookieOptions ) => void; names: () => string[] };
export type HeaderJar = Jar & { outgoing: () => string[] };
export type CookieDocument = { cookie: string };
export type StorageEvent = { key: string | null; newValue: string | null; storageArea?: unknown };
export type Listeners = { add: ( key: string, onChange: Change ) => () => void; fire: ( key: string, value: string | null ) => void; notify: ( onChange: Change, value: string | null ) => void; flush: () => Promise<void> };
export type Kind = "local" | "session" | "memory" | "cookie";
export type Change = ( value: string | null ) => void;
export type Lock = <T>( key: string, work: () => Promise<T> ) => Promise<T>;
export type Storage = {
    get: ( key: string ) => Promise<string | null>;
    set: ( key: string, value: string ) => Promise<void>;
    delete: ( key: string ) => Promise<void>;
    keys: () => Promise<string[]>;
    watch: ( key: string, onChange: Change ) => () => void;
    lock: Lock | undefined;
    flush: () => Promise<void>;
};
export type Driver = {
    get: ( key: string ) => Promise<string | null> | string | null;
    set: ( key: string, value: string ) => Promise<void> | void;
    delete: ( key: string ) => Promise<void> | void;
    keys: () => Promise<string[]> | string[];
    watch?: (( key: string, onChange: Change ) => () => void) | undefined;
    lock?: Lock | undefined;
    flush?: (() => Promise<void>) | undefined;
};
export type WebStorage = adapter.WebStorage;
export type Codec<T> = { encode: ( value: T ) => string; decode: ( text: string ) => T | undefined };
export type Typed<T> = { read: ( key: string ) => Promise<T | undefined>; write: ( key: string, value: T ) => Promise<void>; remove: ( key: string ) => Promise<void> };
export type Envelope = { v: unknown; e?: number | undefined; k?: string | undefined };
export type Place = { kind?: Kind | string | undefined; storage?: Storage | undefined; prefix?: string | undefined };
export type Options = Place & { secret?: string | undefined; sign?: string | undefined; ttl?: number | undefined };
export type Keep = { ttl?: number | undefined; exclusive?: boolean | undefined };
export type Box = {
    readonly storage: Storage;
    flush: () => Promise<void>;
    get: <T = unknown>( key: string ) => Promise<T | undefined>;
    set: <T>( key: string, value: T, keep?: Keep ) => Promise<void>;
    has: ( key: string ) => Promise<boolean>;
    remove: ( key: string ) => Promise<void>;
    pull: <T = unknown>( key: string ) => Promise<T | undefined>;
    keys: () => Promise<string[]>;
    clear: () => Promise<void>;
    remember: <T>( key: string, make: () => T | Promise<T>, keep?: Keep ) => Promise<T>;
    update: <T>( key: string, change: ( current: T | undefined ) => T | undefined | Promise<T | undefined>, keep?: Keep ) => Promise<T | undefined>;
    all: <T = unknown>() => Promise<Record<string, T>>;
    touch: ( key: string, keep?: Keep ) => Promise<boolean>;
    increment: ( key: string, by?: number, keep?: Keep ) => Promise<number>;
    decrement: ( key: string, by?: number, keep?: Keep ) => Promise<number>;
    watch: <T = unknown>( key: string, onChange: ( value: T | undefined ) => void ) => () => void;
};
export type Node<K, V> = { key: K; value: V; older: Node<K, V> | undefined; newer: Node<K, V> | undefined };
export type Kept<V> = { value: V; until: number };
export type Aged<V> = { value: V; at: number };
export type Timed<V> = {
    data: Map<string, Kept<V>>;
    find: ( key: string ) => Kept<V> | undefined;
    put: ( key: string, value: V, life: number | undefined ) => void;
    drop: ( key: string ) => boolean;
    prune: () => number;
};
export type Lru<K, V> = {
    get: ( key: K ) => V | undefined;
    peek: ( key: K ) => V | undefined;
    set: ( key: K, value: V ) => void;
    has: ( key: K ) => boolean;
    delete: ( key: K ) => boolean;
    clear: () => void;
    readonly size: number;
    keys: () => K[];
};
export type Expiring<V> = { get: ( key: string ) => V | undefined; set: ( key: string, value: V, ttl?: number ) => void; has: ( key: string ) => boolean; delete: ( key: string ) => boolean; clear: () => void; prune: () => number; readonly size: number };
export type Remember<V> = { get: ( key: string, load: () => Promise<V>, ttl?: number ) => Promise<V>; forget: ( key: string ) => void; clear: () => void; peek: ( key: string ) => V | undefined; has: ( key: string ) => boolean };
export type Swr<V> = { get: ( key: string, load: () => Promise<V> ) => Promise<V>; forget: ( key: string ) => void; clear: () => void; peek: ( key: string ) => V | undefined; state: ( key: string ) => "missing" | "fresh" | "stale" };
export type Dedupe = <V>( key: string, work: () => Promise<V> ) => Promise<V>;
export type Tagged<V> = { set: ( key: string, value: V, tags: readonly string[], ttl?: number ) => void; get: ( key: string ) => V | undefined; has: ( key: string ) => boolean; invalidate: ( tag: string ) => number; delete: ( key: string ) => void; clear: () => void };
export type Bucket = { count: number; start: number };
export type Taken = { allowed: boolean; remaining: number; retryAfter: number; limit: number };
export type Limiter = { take: ( key: string, cost?: number ) => Taken; peek: ( key: string ) => Taken; reset: ( key: string ) => void; clear: () => void; assert: ( key: string, cost?: number ) => Taken };
